shader_type spatial;

uniform vec4 rim_color : source_color = vec4(0.78, 0.96, 0.26, 1.0);
uniform float rim_power : hint_range(0.5, 8.0) = 2.5;

void fragment() {
  float rim = pow(1.0 - clamp(dot(NORMAL, VIEW), 0.0, 1.0), rim_power);
  ALBEDO = vec3(0.05);
  EMISSION = rim_color.rgb * rim * 2.0;
}

shader_type canvas_item;

uniform float progress : hint_range(0.0, 1.0) = 0.35;
uniform vec4 accent : source_color = vec4(1.0, 0.35, 0.24, 1.0);

void fragment() {
  vec4 tex = texture(TEXTURE, UV);
  float line = step(0.5, fract(UV.y * 48.0 + TIME * 2.0));
  float wipe = step(UV.x, progress);
  COLOR = mix(tex, accent, wipe * line * 0.65);
}

shader_type spatial;

uniform float speed = 0.35;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void fragment() {
  vec2 uv = UV * 3.0 + vec2(TIME * speed);
  float n = hash(floor(uv)) * 0.55 + hash(uv) * 0.45;
  ALBEDO = mix(vec3(0.15), vec3(0.85, 0.9, 1.0), n);
  METALLIC = 1.0;
  ROUGHNESS = 0.25;
}
